import sys
sys.path.append('storage/ariadne')

import jax.numpy as jnp
import optax
from models_fact import Osc2CtxAdaptiveFactorizedL
from losses import mae_with_temporal_curvature

BASE_SEED = 42
BATCH_SIZE = 8

def _define_hyperparameters():
    return {
        'learning_rate': 0.001,
        'rank_k': 320,
        'proj_rank': 48,
        'hidden_size': 64,
        'normalize_u': True,
        'gamma_start': 0.25,
        'gamma_end': 0.98
    }

class Wrapper:
    def __init__(self, rank_k=320, proj_rank=48, hidden_size=64, normalize_u=True, gamma_start=0.25, gamma_end=0.98):
        self.model = Osc2CtxAdaptiveFactorizedL(
            rank_k=rank_k,
            proj_rank=proj_rank,
            hidden_size=hidden_size,
            normalize_u=normalize_u,
            gamma_start=gamma_start,
            gamma_end=gamma_end
        )
        self.needs_rng = False

    def init(self, rng_key, dummy_input):
        return self.model.init(rng_key, dummy_input, training=True)

    def apply(self, params, x, training=False, mutable=None, rngs=None):
        return self.model.apply(params, x, training=training)

def create_network(hparams):
    return Wrapper(
        rank_k=int(hparams.get('rank_k', 320)),
        proj_rank=int(hparams.get('proj_rank', 48)),
        hidden_size=int(hparams.get('hidden_size', 64)),
        normalize_u=bool(hparams.get('normalize_u', True)),
        gamma_start=float(hparams.get('gamma_start', 0.25)),
        gamma_end=float(hparams.get('gamma_end', 0.98))
    )

def compute_loss(predictions, targets, params, x, lam_ortho_V=1e-5):
    # Base MAE + curvature
    loss = mae_with_temporal_curvature(predictions, targets, params, x, lam=1e-4)

    # Add mild orthogonality penalty on V columns only (V shape: [k, p])
    if isinstance(params, dict) and 'params' in params:
        p = params['params']
    else:
        p = params
    V = p.get('V', None)
    if V is not None:
        gram = V.T @ V  # (p, p)
        I = jnp.eye(gram.shape[0], dtype=gram.dtype)
        loss = loss + lam_ortho_V * jnp.mean((gram - I) ** 2)

    return loss

def create_optimizer(learning_rate: float = 0.001):
    # Gradient clipping + Adam
    return optax.chain(
        optax.clip_by_global_norm(1.0),
        optax.adam(learning_rate=learning_rate, eps=1e-8)
    )
